-- ===== Part 2: row-level security and functions =====
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['agent_enrollments', 'agents', 'agent_credentials', 'agent_public_keys', 'agent_heartbeats', 'agent_tasks', 'agent_task_results', 'agent_stream_sessions']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING (organization_id = pcp_current_org()) WITH CHECK (organization_id = pcp_current_org())',
      t
    );
  END LOOP;
END
$$;

-- Enrollment runs before any tenant context exists. Consumption is one conditional UPDATE,
-- so concurrent hosts can never exceed max_uses; every failure returns zero rows.
GRANT UPDATE (uses) ON agent_enrollments TO pcp_rls_definer;

CREATE FUNCTION pcp_consume_enrollment(p_token_hash text)
  RETURNS TABLE (id uuid, organization_id uuid, product_id uuid, environment_id uuid, agent_type text, created_by_user_id uuid)
  LANGUAGE sql VOLATILE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    UPDATE agent_enrollments e
    SET uses = e.uses + 1
    WHERE e.token_hash = p_token_hash
      AND e.uses < e.max_uses
      AND e.expires_at > now()
      AND e.revoked_at IS NULL
    RETURNING e.id, e.organization_id, e.product_id, e.environment_id, e.agent_type::text, e.created_by_user_id
  $$;

-- Agent identity for the mTLS guard: the certificate fingerprint is the only input.
CREATE FUNCTION pcp_agent_by_fingerprint(p_fingerprint text)
  RETURNS TABLE (agent_id uuid, organization_id uuid, product_id uuid, environment_id uuid, agent_status text,
                 not_after timestamptz, superseded_at timestamptz, credential_revoked_at timestamptz)
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT a.id, a.organization_id, a.product_id, a.environment_id, a.status::text,
           c.not_after, c.superseded_at, c.revoked_at
    FROM agent_credentials c
    JOIN agents a ON a.id = c.agent_id
    WHERE c.fingerprint_sha256 = p_fingerprint
  $$;

-- Organization and product of an agent, only when p_user is a member of the organization.
CREATE FUNCTION pcp_resolve_agent_org(p_agent uuid, p_user uuid)
  RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT a.organization_id
    FROM agents a
    JOIN organization_members m ON m.organization_id = a.organization_id AND m.user_id = p_user
    WHERE a.id = p_agent
  $$;

CREATE FUNCTION pcp_resolve_agent_product(p_agent uuid, p_user uuid)
  RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT a.product_id
    FROM agents a
    JOIN organization_members m ON m.organization_id = a.organization_id AND m.user_id = p_user
    WHERE a.id = p_agent
  $$;

DO $$
DECLARE
  f text;
BEGIN
  FOREACH f IN ARRAY ARRAY['pcp_consume_enrollment(text)', 'pcp_agent_by_fingerprint(text)', 'pcp_resolve_agent_org(uuid, uuid)', 'pcp_resolve_agent_product(uuid, uuid)']
  LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO pcp_rls_definer', f);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO pcp_app', f);
  END LOOP;
END
$$;
